content:
Wrap the input and icon in a relatively positioned container, then absolutely position the SVG on the right. Make the icon a `<button>` so it’s clickable and accessible.

### Example in React

```jsx
function SearchInput({ value, onChange, onSearch }) {
  return (
    <div style={{ position: "relative", width: "300px" }}>
      <input
        type="text"
        value={value}
        onChange={onChange}
        placeholder="Search..."
        style={{
          width: "100%",
          padding: "10px 40px 10px 12px", // right padding for icon space
          fontSize: "16px",
          boxSizing: "border-box"
        }}
      />

      <button
        type="button"
        onClick={() => onSearch(value)}
        style={{
          position: "absolute",
          right: "10px",
          top: "50%",
          transform: "translateY(-50%)",
          background: "transparent",
          border: "none",
          padding: 0,
          cursor: "pointer",
          display: "flex",
          alignItems: "center",
          justifyContent: "center"
        }}
      >
        <svg
          xmlns="http://www.w3.org/2000/svg"
          width="20"
          height="20"
          viewBox="0 0 24 24"
          fill="none"
          stroke="currentColor"
          strokeWidth="2"
          strokeLinecap="round"
          strokeLinejoin="round"
        >
          <circle cx="11" cy="11" r="8"></circle>
          <line x1="21" y1="21" x2="16.65" y2="16.65"></line>
        </svg>
      </button>
    </div>
  );
}
```

### Usage

```jsx
import { useState } from "react";

export default function App() {
  const [search, setSearch] = useState("");

  const handleSearch = (value) => {
    console.log("Searching for:", value);
  };

  return (
    <SearchInput
      value={search}
      onChange={(e) => setSearch(e.target.value)}
      onSearch={handleSearch}
    />
  );
}
```

---

### Important points
- `position: relative` on wrapper
- `position: absolute` on button/icon
- extra `padding-right` on input so text doesn’t overlap the icon
- use a `<button>` instead of plain SVG for click handling

---

### If you want plain HTML/CSS/JS version

```html
<div class="input-wrapper">
  <input id="searchInput" type="text" placeholder="Search..." />
  <button id="searchBtn" type="button" class="icon-btn">
    <svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="2">
      <circle cx="11" cy="11" r="8"></circle>
      <line x1="21" y1="21" x2="16.65" y2="16.65"></line>
    </svg>
  </button>
</div>

<script>
  document.getElementById("searchBtn").addEventListener("click", function () {
    const value = document.getElementById("searchInput").value;
    console.log("Searching for:", value);
  });
</script>

<style>
  .input-wrapper {
    position: relative;
    width: 300px;
  }

  .input-wrapper input {
    width: 100%;
    padding: 10px 40px 10px 12px;
    box-sizing: border-box;
  }

  .icon-btn {
    position: absolute;
    right: 10px;
    top: 50%;
    transform: translateY(-50%);
    background: transparent;
    border: none;
    cursor: pointer;
    padding: 0;
  }
</style>
```

